from verify import *
def speeds(M, bar_turns_per_h):
    # returns dict mobile -> signed turns/h (cw positive) through meshes passing; and conflicts
    from fractions import Fraction
    sp={'barrel':Fraction(bar_turns_per_h)}
    adj={}
    for m in M.j['meshes']:
        adj.setdefault(m['driver'],[]).append((m['driven'],Fraction(m['driver_teeth'],m['driven_teeth']),m))
        adj.setdefault(m['driven'],[]).append((m['driver'],Fraction(m['driven_teeth'],m['driver_teeth']),m))
    st=['barrel']
    while st:
        x=st.pop()
        for y,r,_ in adj.get(x,[]):
            v=-sp[x]*r
            if y in sp:
                if sp[y]!=v: print('SPEED CONFLICT',x,y,sp[y],v)
            else: sp[y]=v; st.append(y)
    return sp
def mesh_steps(M,mesh,dN=0.0,stride=1,full=True):
    Dn,Nn=mesh['driver'],mesh['driven']; zD,zN=mesh['driver_teeth'],mesh['driven_teeth']
    D=M.mob[Dn]; N=M.mob[Nn]; aD=M.axis[Dn]; aN=M.axis[Nn]
    a=math.dist(aD,aN); m=2*a/(zD+zN)
    if dN!=0.0:
        ux,uy=(aN[0]-aD[0])/a,(aN[1]-aD[1])/a
        if a<1e-12: ux,uy=1.0,0.0
        N=trans(N,(ux*dN,uy*dN,0)); aN=(aN[0]+ux*dN,aN[1]+uy*dN)
    nst=8*max(zD,zN)
    res=dict(jam=0.0,engaged_bad=0,Vmin=1e9,VHmin=1e9,Hmin=1e9,thr=0.5*m*m,ok=True,msg=[])
    def pos(i):
        th=i*360.0/(8*zD)
        return rotz(D,aD,th), rotz(N,aN,-th*zD/zN)
    idx=list(range(0,nst,stride)) if not full else list(range(nst))
    for i in idx:
        fr=[i]
        if i%8==0: fr+= [i+1/3,i+1/5]
        for f in fr:
            Dr,Nr=pos(f)
            v=ivol(Dr,Nr)
            res['jam']=max(res['jam'],v)
            if v>0.01: res['ok']=False; res['msg'].append('jam step %s %.4f'%(f,v)); 
            if f==i and i%4==0 and v==0.0:
                d=kernel.min_distance(Dr,Nr,1.0)
                if d>0.1: res['ok']=False; res['msg'].append('engaged step %d dist %.3f'%(i,d))
        if i%8==0:
            Dr,Nr=pos(i)
            Dx=rotz(Dr,aD,90.0/zD)
            reg=(Dx^Nr)-Dr
            V=reg.volume()
            if reg.is_empty() or V<=0: Hh=0
            else:
                bb=reg.bounding_box(); Hh=bb[5]-bb[2]
            res['Vmin']=min(res['Vmin'],V)
            if Hh>0: res['Hmin']=min(res['Hmin'],Hh); res['VHmin']=min(res['VHmin'],V/Hh)
            if V<0.001 or Hh<=0 or V/Hh<=res['thr']:
                res['ok']=False; res['msg'].append('drive step %d V %.4f H %.3f V/H %.4f thr %.4f'%(i,V,Hh,V/max(Hh,1e-9),res['thr']))
        if len(res['msg'])>5: break
    return res
def check45(M,bar,stride=1,only=None):
    ok=True; info={}
    for mesh in M.j['meshes']:
        key=mesh['driver']+'>'+mesh['driven']
        if only and key not in only: continue
        t=time.time()
        r0=mesh_steps(M,mesh,0.0,stride)
        r1=mesh_steps(M,mesh,0.03,stride); r2=mesh_steps(M,mesh,-0.03,stride)
        for tag,r in (('nom',r0),('away',r1),('towards',r2)):
            report('mesh %s %s'%(key,tag),r['ok'],'jam %.4f Vmin %.4f V/H %.4f thr %.4f H %.3f %s %.0fs'%(r['jam'],r['Vmin'],r['VHmin'],r['thr'],r['Hmin'],r['msg'][:2],time.time()-t))
            ok=ok and r['ok']
        info[key]=r0
    return ok,info
if __name__=='__main__':
    fn=sys.argv[1]; stride=int(sys.argv[2]) if len(sys.argv)>2 else 1
    M=Mov(fn)
    only=sys.argv[3].split(',') if len(sys.argv)>3 else None
    check45(M,None,stride,only)
