def check45(M,bar,stride=1,only=None):
    ok=True; info={}
    for mesh in M.j['meshes']:
        key=mesh['driver']+'>'+mesh['driven']
        if only and key not in only: continue
        t=time.time()
        r0=mesh_steps(M,mesh,0.0,stride)
        r1=mesh_steps(M,mesh,0.03,stride); r2=mesh_steps(M,mesh,-0.03,stride)
        for tag,r in (('nom',r0),('away',r1),('towards',r2)):
