            ok=ok and r['ok']
        info[key]=r0
    return ok,info
if __name__=='__main__':
    fn=sys.argv[1]; stride=int(sys.argv[2]) if len(sys.argv)>2 else 1
    M=Mov(fn)
    only=sys.argv[3].split(',') if len(sys.argv)>3 else None
    check45(M,None,stride,only)
