from verify3 import *
def check_assembly(M):
    A=json.load(open(DEL+'/assembly.json'))
    allparts={}
    for k,v in M.j['mobiles'].items():
        for n in v['parts']: allparts[n]=load_part(n)
    for n in M.j['fixed']: allparts[n]=load_part(n)
    allparts['barrel']=barrel()
    seen=[]; order=[]
    for n in A['order']:
        if n in allparts and n not in order: order.append(n)
    # bbox of complete movement
    lo=np.min([allparts[n].bounding_box()[:3] for n in allparts],axis=0)-5; hi=np.max([allparts[n].bounding_box()[3:] for n in allparts],axis=0)+5
    ok_count=0
    for idx,n in enumerate(order):
        msgs=[]
        P=[np.array(T,float) for T in A['paths'][n]]
        man=allparts[n]
        good=True
        if not (2<=len(P)<=1500): good=False; msgs.append('npose')
        for T in P:
            R=T[:3,:3]
            if not np.isfinite(T).all() or np.abs(R.T@R-np.eye(3)).max()>1e-6 or abs(np.linalg.det(R)-1)>1e-6 or np.abs(T[3]-[0,0,0,1]).max()>1e-6: good=False; msgs.append('matrix'); break
        if np.abs(P[-1]-np.eye(4)).max()>1e-6: good=False; msgs.append('last not identity')
        V=kernel.verts(man)
        def world(T): return V@T[:3,:3].T+T[:3,3]
        w0=world(P[0]); b0=(w0.min(0),w0.max(0))
        if not (np.any(b0[1]<lo) or np.any(b0[0]>hi)): good=False; msgs.append('first pose bbox not outside')
        for a,b in zip(P[:-1],P[1:]):
            if np.linalg.norm(world(a)-world(b),axis=1).max()>0.2: good=False; msgs.append('step>0.2'); break
        worst=0.0
        for j,T in enumerate(P):
            mp=man.transform(T[:3,:4].tolist())
            for m2 in order[:idx]:
                v=ivol(mp,allparts[m2]); 
                if v>worst: worst=v; wj=(j,m2)
        if worst>0.01: good=False; msgs.append('collision %s'%(wj,)); 
        report('assembly %d %s'%(idx,n),good,'worst %.4f %s'%(worst,msgs))
        ok_count+=good
    print('installed',ok_count,'of',len(order))
if __name__=='__main__':
    check_assembly(Mov('movement.json'))
